import { el, replace } from '../dom.js'
import { keyOf } from '../indexer.js'
import { hiddenSet, saveHidden } from '../flex.js'

// <img> with gateway-fallback: advance through candidates on error, then
// degrade to a text placeholder. All hosts are https (enforced by CSP img-src).
export function fallbackImg(candidates, attrs = {}) {
  if (!candidates.length) return el('div', { class: 'noimg' }, 'no image')
  let i = 0
  const img = el('img', {
    src: candidates[0], loading: 'lazy', alt: '',
    onerror: () => {
      i += 1
      if (i < candidates.length) img.src = candidates[i]
      else img.replaceWith(el('div', { class: 'noimg' }, 'no image'))
    },
    ...attrs,
  })
  return img
}

// filter/sort state lives here so it survives re-renders
export const filters = { q: '', chain: 'all', account: 'all', group: true }

export function renderGallery(container, state, onSelect, onUnhide) {
  if (state.scanning) {
    return replace(container,
      el('h2', {}, state.progress || 'Scanning…'),
      el('div', { class: 'grid' }, Array.from({ length: 8 }, () => el('div', { class: 'skel' }))))
  }
  if (!state.nfts.length) {
    return replace(container, el('div', { class: 'empty' },
      'Connect your KeepKey Vault, then scan to see NFTs across your accounts (Ethereum + Base).'))
  }
  const all = state.nfts.filter((n) => !n.spam && !hiddenSet.has(keyOf(n)))
  const hidden = state.nfts.filter((n) => n.spam || hiddenSet.has(keyOf(n)))
  const q = filters.q.trim().toLowerCase()
  const visible = all.filter((n) =>
    (filters.chain === 'all' || String(n.chainId) === filters.chain) &&
    (filters.account === 'all' || String(n.ownerIndex) === filters.account) &&
    (!q || n.name.toLowerCase().includes(q) || String(n.tokenId).includes(q) || (n.collectionName || '').toLowerCase().includes(q)))

  const rerender = () => renderGallery(container, state, onSelect, onUnhide)
  const bar = el('div', { class: 'filters' },
    el('input', { type: 'search', placeholder: 'search name, token id, collection…', value: filters.q,
      oninput: (e) => { filters.q = e.target.value; rerender(); container.querySelector('input[type=search]')?.focus() } }),
    el('select', { onchange: (e) => { filters.chain = e.target.value; rerender() } },
      el('option', { value: 'all', selected: filters.chain === 'all' || null }, 'all chains'),
      [...new Set(state.nfts.map((n) => n.chainId))].map((id) =>
        el('option', { value: String(id), selected: filters.chain === String(id) || null },
          state.nfts.find((n) => n.chainId === id).chainName))),
    el('select', { onchange: (e) => { filters.account = e.target.value; rerender() } },
      el('option', { value: 'all', selected: filters.account === 'all' || null }, 'all accounts'),
      [...new Set(state.nfts.map((n) => n.ownerIndex))].sort().map((i) =>
        el('option', { value: String(i), selected: filters.account === String(i) || null }, `account #${i}`))),
    el('button', { class: filters.group ? 'tab on' : 'tab', onclick: () => { filters.group = !filters.group; rerender() } },
      filters.group ? 'grouped by collection' : 'flat grid'),
    el('span', { style: 'color:var(--dim);font-size:12px' }, `${visible.length} of ${all.length}`))

  // group by collection (or chain when grouping is off)
  const groups = {}
  visible.forEach((n) => {
    const key = filters.group ? `${n.collectionName || 'Unnamed collection'} · ${n.chainName}` : n.chainName
    ;(groups[key] ||= []).push(n)
  })
  const sections = Object.entries(groups)
    .sort((a, b) => b[1].length - a[1].length)
    .flatMap(([title, list]) => [
      el('h2', {}, `${title} — ${list.length}`),
      el('div', { class: 'grid' }, list.map((n) => {
        const card = el('div', { class: 'card', onclick: () => onSelect(n, card) },
          fallbackImg(n.images),
          el('div', { class: 'meta' },
            el('div', { class: 'nm' }, n.name),
            el('div', { class: 'ch' }, `${n.chainName} · ${n.standard ?? ''}`)))
        card.dataset.key = keyOf(n)
        return card
      })),
    ])
  sections.unshift(bar)

  let hiddenSection = null
  if (hidden.length) {
    // hidden items render as TEXT ONLY — their images are never fetched
    const list = el('ul', { style: 'display:none' }, hidden.map((n) =>
      el('li', {},
        el('span', {}, `${n.name.slice(0, 60)} · ${n.chainName} · ${n.spam ? 'auto-flagged spam' : 'hidden by you'}`),
        el('button', { class: 'ghost', onclick: () => { hiddenSet.delete(keyOf(n)); saveHidden(); n.spam = false; onUnhide() } }, 'unhide'))))
    hiddenSection = el('div', { id: 'hiddenSection' },
      el('button', {
        class: 'ghost',
        onclick: () => { list.style.display = list.style.display === 'none' ? 'block' : 'none' },
      }, `${hidden.length} hidden (spam + hidden by you) — show`),
      list)
  }
  replace(container, sections, hiddenSection)
}
