import { el, replace } from '../dom.js'
import { fetchActivity } from '../activity.js'

const short = (a) => (a ? `${String(a).slice(0, 8)}…${String(a).slice(-4)}` : '?')

export function createActivityView(getAccounts) {
  const box = el('div')
  let state = { loading: false, loaded: false, rows: [] }

  async function load() {
    state.loading = true; render()
    try { state.rows = await fetchActivity(getAccounts()); state.loaded = true }
    finally { state.loading = false; render() }
  }

  function render() {
    if (state.loading) return replace(box, el('h2', {}, 'Activity'), el('div', { class: 'empty' }, 'Loading transfer history…'))
    if (!state.loaded) return replace(box, el('h2', {}, 'Activity'),
      el('div', { class: 'approw' }, el('span', { style: 'flex:1' }, 'NFT transfers in and out of your accounts.'),
        el('button', { class: 'ghost', onclick: load }, 'Load activity')))
    if (!state.rows.length) return replace(box, el('h2', {}, 'Activity'), el('div', { class: 'empty' }, 'No NFT transfers found.'))
    replace(box,
      el('h2', {}, `Activity — ${state.rows.length}`),
      el('div', {}, state.rows.map((r) =>
        el('div', { class: 'actrow' },
          el('span', { class: 'when' }, r.when ? r.when.toISOString().slice(0, 10) : '—'),
          el('span', { class: 'what' },
            el('span', { class: `dir ${r.direction}` }, r.direction === 'in' ? 'received ' : 'sent '),
            `${r.tokenName}${r.tokenId != null ? ' #' + r.tokenId : ''} `,
            el('span', { style: 'color:var(--dim)' }, `${r.direction === 'in' ? 'from' : 'to'} ${r.counterpartyName || short(r.counterparty)}`),
            r.isScamCounterparty ? el('span', { style: 'color:var(--bad)' }, ' ⚠ flagged scam') : null,
            el('span', { style: 'color:var(--dim)' }, ` · ${r.chainName} · #${r.account}`)),
          el('a', { href: `${r.explorer}/tx/${r.txHash}`, target: '_blank', rel: 'noopener noreferrer' }, 'tx ↗')))),
      el('div', { class: 'btnrow' }, el('button', { class: 'ghost', onclick: load }, 'Refresh')))
  }

  render()
  return { box, load }
}
