// NFT transfer history across accounts/chains (Blockscout).
import { CHAINS } from './config.js'

const eq = (a, b) => a && b && String(a).toLowerCase() === String(b).toLowerCase()

export async function fetchActivity(accounts) {
  const rows = []
  await Promise.all(accounts.flatMap((a) => CHAINS.map(async (chain) => {
    try {
      const r = await fetch(`${chain.scout}/api/v2/addresses/${a.address}/token-transfers?type=ERC-721%2CERC-1155`)
      if (!r.ok) return
      const { items = [] } = await r.json()
      for (const it of items) {
        const outgoing = eq(it.from?.hash, a.address)
        rows.push({
          when: it.timestamp ? new Date(it.timestamp) : null,
          direction: outgoing ? 'out' : 'in',
          counterparty: outgoing ? it.to?.hash : it.from?.hash,
          counterpartyName: (outgoing ? it.to?.name : it.from?.name) || null,
          isScamCounterparty: !!(outgoing ? it.to?.is_scam : it.from?.is_scam),
          tokenName: it.token?.name || 'NFT',
          tokenId: it.total?.token_id ?? it.token_id ?? null,
          chainName: chain.name, explorer: chain.explorer,
          txHash: it.transaction_hash,
          account: a.index,
        })
      }
    } catch { /* indexer flake */ }
  })))
  return rows.sort((x, y) => (y.when?.getTime() || 0) - (x.when?.getTime() || 0)).slice(0, 100)
}
