// NFT transfer transactions: build calldata, estimate, hardware-sign via
// Vault, broadcast via public RPC, await receipt. The device screen is the
// final authority on what gets signed — this module's job is to construct
// honestly and show everything before asking.
import { createPublicClient, http, fallback, encodeFunctionData, parseAbi, isAddress, getAddress, formatEther } from 'viem'
import { mainnet, base } from 'viem/chains'
import { normalize } from 'viem/ens'
import { chainById, HARDENED } from './config.js'
import { signTransaction } from './vault.js'

const VIEM_CHAINS = { 1: mainnet, 8453: base }
const clients = {}
export function client(chainId) {
  if (!clients[chainId]) {
    const cfg = chainById(chainId)
    clients[chainId] = createPublicClient({ chain: VIEM_CHAINS[chainId], transport: fallback(cfg.rpcs.map((u) => http(u))) })
  }
  return clients[chainId]
}

const ERC721_ABI = parseAbi(['function safeTransferFrom(address from, address to, uint256 tokenId)'])
const ERC1155_ABI = parseAbi(['function safeTransferFrom(address from, address to, uint256 id, uint256 amount, bytes data)'])

// Accepts 0x address or ENS name (resolved via mainnet ENS regardless of the
// NFT's chain — standard wallet behavior). Returns checksummed address.
export async function resolveRecipient(input) {
  const s = input.trim()
  if (isAddress(s)) return getAddress(s)
  if (/^[a-z0-9-]+(\.[a-z0-9-]+)*\.eth$/i.test(s)) {
    const addr = await client(1).getEnsAddress({ name: normalize(s) })
    if (!addr) throw new Error(`ENS name ${s} does not resolve`)
    return getAddress(addr)
  }
  throw new Error('recipient must be a 0x address or an ENS name')
}

export async function prepareTransfer(n, to) {
  const c = client(n.chainId)
  const from = getAddress(n.owner)
  const data = n.standard === 'ERC-1155'
    ? encodeFunctionData({ abi: ERC1155_ABI, functionName: 'safeTransferFrom', args: [from, to, BigInt(n.tokenId), 1n, '0x'] })
    : encodeFunctionData({ abi: ERC721_ABI, functionName: 'safeTransferFrom', args: [from, to, BigInt(n.tokenId)] })
  const [gas, fees, nonce] = await Promise.all([
    c.estimateGas({ account: from, to: n.contract, data }),
    c.estimateFeesPerGas(),
    c.getTransactionCount({ address: from, blockTag: 'pending' }),
  ])
  const gasLimit = (gas * 12n) / 10n
  const feeWei = gasLimit * fees.maxFeePerGas
  return {
    tx: {
      to: n.contract, data, nonce, gasLimit,
      maxFeePerGas: fees.maxFeePerGas, maxPriorityFeePerGas: fees.maxPriorityFeePerGas,
      chainId: n.chainId,
    },
    feeEstimate: formatEther(feeWei),
  }
}

const hex = (v) => '0x' + BigInt(v).toString(16)

export async function signAndBroadcast(n, prep) {
  const out = await signTransaction({
    addressNList: [HARDENED + 44, HARDENED + 60, HARDENED + n.ownerIndex, 0, 0],
    nonce: hex(prep.tx.nonce), gasLimit: hex(prep.tx.gasLimit),
    maxFeePerGas: hex(prep.tx.maxFeePerGas), maxPriorityFeePerGas: hex(prep.tx.maxPriorityFeePerGas),
    value: '0x0', to: prep.tx.to, chainId: prep.tx.chainId, data: prep.tx.data,
  })
  const raw = out?.serialized || out?.raw || out?.signedTx || (typeof out === 'string' ? out : null)
  if (!raw || !/^0x[0-9a-fA-F]+$/.test(raw)) {
    throw new Error('unexpected sign-transaction response: ' + JSON.stringify(out).slice(0, 200))
  }
  const hash = await client(n.chainId).sendRawTransaction({ serializedTransaction: raw })
  return hash
}

export const waitForReceipt = (chainId, hash) =>
  client(chainId).waitForTransactionReceipt({ hash, timeout: 180_000 })
