// Approvals discovery + revocation.
// Free public RPCs refuse full-history log scans, so we derive candidate
// approvals from the account's own outgoing transactions (Blockscout decodes
// them) and then confirm CURRENT state on-chain with isApprovedForAll /
// allowance. On-chain state is the truth; history is only the candidate list.
import { parseAbi, getAddress, maxUint256 } from 'viem'
import { CHAINS, chainById } from './config.js'
import { client } from './tx.js'

const IS_APPROVED_ABI = parseAbi(['function isApprovedForAll(address owner, address operator) view returns (bool)'])
const ALLOWANCE_ABI = parseAbi(['function allowance(address owner, address spender) view returns (uint256)'])
const DECIMALS_ABI = parseAbi(['function decimals() view returns (uint8)'])

async function txPage(chain, address) {
  try {
    const r = await fetch(`${chain.scout}/api/v2/addresses/${address}/transactions?filter=from`)
    if (!r.ok) return []
    return (await r.json()).items || []
  } catch { return [] }
}

const paramOf = (decoded, name) =>
  decoded?.parameters?.find((p) => p.name === name)?.value

// Returns [{ chainId, chainName, contract, contractName, operator, kind,
//            amount?, isScamOperator }]
export async function findApprovals(accounts, onProgress) {
  const out = []
  for (const chain of CHAINS) {
    for (const acct of accounts) {
      const txs = await txPage(chain, acct.address)
      const candidates = []
      for (const t of txs) {
        const m = t.method
        if (m !== 'setApprovalForAll' && m !== 'approve') continue
        const d = t.decoded_input
        const operator = paramOf(d, 'operator') || paramOf(d, 'spender') || paramOf(d, 'to')
        if (!operator) continue
        candidates.push({
          contract: t.to?.hash, contractName: t.to?.name || null,
          isScamContract: !!t.to?.is_scam,
          operator: getAddress(operator),
          kind: m === 'setApprovalForAll' ? 'collection' : 'token',
          owner: acct.address, ownerIndex: acct.index,
          chainId: chain.id, chainName: chain.name,
        })
      }
      // de-dupe (contract, operator, kind) then confirm live state
      const seen = new Set()
      for (const c of candidates) {
        const key = `${c.chainId}:${c.contract}:${c.operator}:${c.kind}`.toLowerCase()
        if (seen.has(key)) continue
        seen.add(key)
        try {
          const cl = client(c.chainId)
          if (c.kind === 'collection') {
            const active = await cl.readContract({ address: c.contract, abi: IS_APPROVED_ABI, functionName: 'isApprovedForAll', args: [c.owner, c.operator] })
            if (active) out.push({ ...c, active: true })
          } else {
            const allowance = await cl.readContract({ address: c.contract, abi: ALLOWANCE_ABI, functionName: 'allowance', args: [c.owner, c.operator] })
            if (allowance > 0n) {
              let decimals = 18
              try { decimals = await cl.readContract({ address: c.contract, abi: DECIMALS_ABI, functionName: 'decimals' }) } catch {}
              const whole = allowance / 10n ** BigInt(decimals)
              // anything beyond a trillion tokens is "unlimited" in practice
              out.push({ ...c, active: true, amount: allowance, decimals, whole,
                unlimited: allowance > maxUint256 / 2n || whole > 1_000_000_000_000n })
            }
          }
        } catch { /* not an ERC-721/20 or call failed — skip */ }
        onProgress?.(out.length)
      }
    }
  }
  return out
}

export const revokeCalldata = (approval) => approval.kind === 'collection'
  ? { abi: parseAbi(['function setApprovalForAll(address operator, bool approved)']), functionName: 'setApprovalForAll', args: [approval.operator, false] }
  : { abi: parseAbi(['function approve(address spender, uint256 amount)']), functionName: 'approve', args: [approval.operator, 0n] }
